import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1788377613000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 44 tools: 29 read, 15 write. With <code>AUDIOBOOKSHELF_READ_ONLY=true</code> the write tools are not registered at all.</p><p>All 44 are registered unless you say otherwise. <code>AUDIOBOOKSHELF_ALLOW_TOOLS</code> and <code>AUDIOBOOKSHELF_DENY_TOOLS</code> narrow the list to the ones you want, and <code>AUDIOBOOKSHELF_ALLOW_TOOLS=essential</code> selects the 8 marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>Every tool that returns media accepts <code>detail</code> — <code>&quot;compact&quot;</code> (the default) returns a projection with the fields that matter for browsing, <code>&quot;full&quot;</code> returns the raw Audiobookshelf object, which is very large.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — a dialog the model cannot answer on its behalf. Where the client cannot show one, it falls back to a two-call <code>confirm_token</code>, and says which of the two it was. <code>ELICITATION=false</code> takes that fallback deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. They are a hint a client may ignore; the dialog is enforced here and cannot be.</p><p>Every tool declares an <code>outputSchema</code> and answers with <code>structuredContent</code> beside the text block, so a client can use a result without parsing prose. The tools that report library metadata carry <code>untrusted: true</code> and <code>source: &quot;audiobookshelf&quot;</code> as fields of that object. The documents are described as open objects with the top-level keys this server builds: <code>detail: &quot;full&quot;</code> hands the API record back whole, so a strict shape would turn that mode into a failed call.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="list-libraries" tabindex="-1"><code>list_libraries</code> <a class="header-anchor" href="#list-libraries" aria-label="Permalink to “list_libraries”">​</a></h3><p><strong>List libraries</strong> — read-only, <strong>essential</strong></p><p>Lists the Audiobookshelf libraries the API key’s user can access, with their id, name and media type (book or podcast). Start here — every other library tool needs a library id.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-library" tabindex="-1"><code>get_library</code> <a class="header-anchor" href="#get-library" aria-label="Permalink to “get_library”">​</a></h3><p><strong>Get library</strong> — read-only</p><p>Fetches a single library including its folders and scanner settings.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-library-stats" tabindex="-1"><code>get_library_stats</code> <a class="header-anchor" href="#get-library-stats" aria-label="Permalink to “get_library_stats”">​</a></h3><p><strong>Get library stats</strong> — read-only</p><p>Statistics for one library: number of items, authors and genres, total duration and size, longest and largest items.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr></tbody></table><h3 id="get-library-filter-data" tabindex="-1"><code>get_library_filter_data</code> <a class="header-anchor" href="#get-library-filter-data" aria-label="Permalink to “get_library_filter_data”">​</a></h3><p><strong>Get library filter data</strong> — read-only</p><p>Returns the values that can be filtered on in this library: authors, genres, tags, series, narrators, languages and publishers, each with the id or name to pass to list_library_items as filter_value.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr></tbody></table><h3 id="list-library-items" tabindex="-1"><code>list_library_items</code> <a class="header-anchor" href="#list-library-items" aria-label="Permalink to “list_library_items”">​</a></h3><p><strong>List library items</strong> — read-only, <strong>essential</strong></p><p>Lists items (books or podcasts) of a library, paginated, sortable and filterable. Use get_library_filter_data first to learn the valid filter values. Filter groups — valued (need filter_value): genres, tags, series, authors, progress, narrators, publishers, publishedDecades, missing, languages, tracks, ebooks; standalone: issues, feed-open, share-open, recent.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>page</code></td><td>integer</td><td>no</td><td>0-based page number, default 0</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 25, max 100</td></tr><tr><td><code>sort</code></td><td>string</td><td>no</td><td>Sort key in dot notation. Common values: media.metadata.title, media.metadata.authorName, media.metadata.publishedYear, media.duration, birthtimeMs, addedAt, size, progress, random.</td></tr><tr><td><code>descending</code></td><td>boolean</td><td>no</td><td>Reverse the sort order, default false</td></tr><tr><td><code>filter_group</code></td><td><code>&quot;genres&quot;</code> | <code>&quot;tags&quot;</code> | <code>&quot;series&quot;</code> | <code>&quot;authors&quot;</code> | <code>&quot;progress&quot;</code> | <code>&quot;narrators&quot;</code> | <code>&quot;publishers&quot;</code> | <code>&quot;publishedDecades&quot;</code> | <code>&quot;missing&quot;</code> | <code>&quot;languages&quot;</code> | <code>&quot;tracks&quot;</code> | <code>&quot;ebooks&quot;</code> | <code>&quot;issues&quot;</code> | <code>&quot;feed-open&quot;</code> | <code>&quot;share-open&quot;</code> | <code>&quot;recent&quot;</code></td><td>no</td><td>Filter group. The server encodes group and value into the base64 form its API expects.</td></tr><tr><td><code>filter_value</code></td><td>string</td><td>no</td><td>Value for filter_group: an id for authors/series, a name for genres/tags/narrators/languages/publishers, one of finished/in-progress/not-started/not-finished for progress. Must be omitted for the standalone groups.</td></tr><tr><td><code>collapse_series</code></td><td>boolean</td><td>no</td><td>Collapse books of the same series into one entry</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="search-library" tabindex="-1"><code>search_library</code> <a class="header-anchor" href="#search-library" aria-label="Permalink to “search_library”">​</a></h3><p><strong>Search a library</strong> — read-only, <strong>essential</strong></p><p>Full-text search within one library. Matches books, podcasts, series, authors, narrators and tags. Use this for &quot;do I own X?&quot; questions; use list_library_items with a filter for &quot;show me all X&quot; questions.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>q</code></td><td>string</td><td>yes</td><td>Search query</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 12, max 100</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-personalized-shelves" tabindex="-1"><code>get_personalized_shelves</code> <a class="header-anchor" href="#get-personalized-shelves" aria-label="Permalink to “get_personalized_shelves”">​</a></h3><p><strong>Get personalized shelves</strong> — read-only</p><p>The shelves of the Audiobookshelf home screen for this user: Continue Listening, Continue Series, Recently Added, Newest Episodes, Listen Again and so on. The fastest answer to &quot;what am I listening to right now?&quot;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 10, max 100</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-series" tabindex="-1"><code>list_series</code> <a class="header-anchor" href="#list-series" aria-label="Permalink to “list_series”">​</a></h3><p><strong>List series</strong> — read-only</p><p>Lists the series of a book library with their number of books and total duration. To list the books of one series, call list_library_items with filter_group=&quot;series&quot; and filter_value=&lt;series id&gt;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>page</code></td><td>integer</td><td>no</td><td>0-based page number, default 0</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 25, max 100</td></tr><tr><td><code>sort</code></td><td>string</td><td>no</td><td>Sort key, e.g. name, numBooks, addedAt, totalDuration</td></tr><tr><td><code>descending</code></td><td>boolean</td><td>no</td><td>Reverse the sort order</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-series" tabindex="-1"><code>get_series</code> <a class="header-anchor" href="#get-series" aria-label="Permalink to “get_series”">​</a></h3><p><strong>Get series</strong> — read-only</p><p>Fetches a single series by id, including its books. To list the books with paging and sorting, use list_library_items with filter_group=&quot;series&quot; instead.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>series_id</code></td><td>string</td><td>yes</td><td>Series id</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-authors" tabindex="-1"><code>list_authors</code> <a class="header-anchor" href="#list-authors" aria-label="Permalink to “list_authors”">​</a></h3><p><strong>List authors</strong> — read-only</p><p>Lists all authors of a book library with their number of books. To list the books of one author, call list_library_items with filter_group=&quot;authors&quot; and filter_value=&lt;author id&gt;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library id, as returned by list_libraries</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-author" tabindex="-1"><code>get_author</code> <a class="header-anchor" href="#get-author" aria-label="Permalink to “get_author”">​</a></h3><p><strong>Get author</strong> — read-only</p><p>Fetches a single author, optionally with the library items attributed to them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>author_id</code></td><td>string</td><td>yes</td><td>Author id</td></tr><tr><td><code>include_items</code></td><td>boolean</td><td>no</td><td>Also return the author’s library items, default false</td></tr><tr><td><code>library_id</code></td><td>string</td><td>no</td><td>Restrict the returned items to this library</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-tags" tabindex="-1"><code>list_tags</code> <a class="header-anchor" href="#list-tags" aria-label="Permalink to “list_tags”">​</a></h3><p><strong>List tags</strong> — read-only</p><p>Lists all tags used on the server, across libraries. Tags are the user-defined labels on library items.</p><p>Takes no parameters.</p><h3 id="list-genres" tabindex="-1"><code>list_genres</code> <a class="header-anchor" href="#list-genres" aria-label="Permalink to “list_genres”">​</a></h3><p><strong>List genres</strong> — read-only</p><p>Lists all genres used on the server, across libraries. Genres come from the media metadata, not from the user.</p><p>Takes no parameters.</p><h3 id="get-server-status" tabindex="-1"><code>get_server_status</code> <a class="header-anchor" href="#get-server-status" aria-label="Permalink to “get_server_status”">​</a></h3><p><strong>Get server status</strong> — read-only</p><p>Version and initialization state of the Audiobookshelf server. Useful to check connectivity and whether the server is new enough for API keys (2.26.0 or later).</p><p>Takes no parameters.</p><h3 id="get-library-item" tabindex="-1"><code>get_library_item</code> <a class="header-anchor" href="#get-library-item" aria-label="Permalink to “get_library_item”">​</a></h3><p><strong>Get library item</strong> — read-only, <strong>essential</strong></p><p>Fetches one book or podcast including its metadata, tags and the listening progress of the API key’s user. Chapters, audio files and tracks are not part of the compact projection — use get_item_chapters for chapters, or detail=&quot;full&quot; for everything.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-item-chapters" tabindex="-1"><code>get_item_chapters</code> <a class="header-anchor" href="#get-item-chapters" aria-label="Permalink to “get_item_chapters”">​</a></h3><p><strong>Get item chapters</strong> — read-only, <strong>essential</strong></p><p>Returns the chapter list of a book with start and end times in seconds. Separate from get_library_item because long audiobooks can have hundreds of chapters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr></tbody></table><h3 id="get-podcast-episode" tabindex="-1"><code>get_podcast_episode</code> <a class="header-anchor" href="#get-podcast-episode" aria-label="Permalink to “get_podcast_episode”">​</a></h3><p><strong>Get podcast episode</strong> — read-only</p><p>Fetches one podcast episode with its publication date, duration and description.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id of the podcast the episode belongs to</td></tr><tr><td><code>episode_id</code></td><td>string</td><td>yes</td><td>Podcast episode id</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-recent-episodes" tabindex="-1"><code>list_recent_episodes</code> <a class="header-anchor" href="#list-recent-episodes" aria-label="Permalink to “list_recent_episodes”">​</a></h3><p><strong>List recent podcast episodes</strong> — read-only</p><p>Lists the most recently published episodes across a podcast library — the &quot;Newest Episodes&quot; view. Only works on libraries with mediaType &quot;podcast&quot;.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Id of a podcast library</td></tr><tr><td><code>page</code></td><td>integer</td><td>no</td><td>0-based page number, default 0</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Episodes per page, default 25, max 100</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-me" tabindex="-1"><code>get_me</code> <a class="header-anchor" href="#get-me" aria-label="Permalink to “get_me”">​</a></h3><p><strong>Get the current user</strong> — read-only</p><p>Returns the Audiobookshelf user the API key acts on behalf of, with their permissions and accessible libraries. The compact projection reports media progress and bookmarks as counts — the full user object embeds every single one of them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-items-in-progress" tabindex="-1"><code>list_items_in_progress</code> <a class="header-anchor" href="#list-items-in-progress" aria-label="Permalink to “list_items_in_progress”">​</a></h3><p><strong>List items in progress</strong> — read-only, <strong>essential</strong></p><p>The items the user has started but not finished, newest first — the &quot;Continue Listening&quot; list across all libraries. The entries carry progressLastUpdate but not the position itself; use get_media_progress for that. For podcasts, recentEpisode names the episode in progress.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 25, max 100</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-media-progress" tabindex="-1"><code>get_media_progress</code> <a class="header-anchor" href="#get-media-progress" aria-label="Permalink to “get_media_progress”">​</a></h3><p><strong>Get media progress</strong> — read-only, <strong>essential</strong></p><p>The listening progress of the current user for one book or podcast episode: position, percentage and whether it is finished. Returns a 404 error when the item has never been started.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>episode_id</code></td><td>string</td><td>no</td><td>Podcast episode id — required for podcast episodes, omitted for books</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-listening-stats" tabindex="-1"><code>get_listening_stats</code> <a class="header-anchor" href="#get-listening-stats" aria-label="Permalink to “get_listening_stats”">​</a></h3><p><strong>Get listening stats</strong> — read-only</p><p>Aggregated listening statistics of the current user: total time, time per weekday, the last 30 days, the ten most listened items and the ten most recent sessions. detail=&quot;full&quot; returns the complete per-day history and the full metadata of every item ever listened to, which is the largest response this API produces.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-year-stats" tabindex="-1"><code>get_year_stats</code> <a class="header-anchor" href="#get-year-stats" aria-label="Permalink to “get_year_stats”">​</a></h3><p><strong>Get stats for a year</strong> — read-only</p><p>The &quot;year in review&quot; statistics of the current user for one calendar year: books finished, time listened, top authors and genres.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>year</code></td><td>integer</td><td>yes</td><td>Calendar year, e.g. 2026</td></tr></tbody></table><h3 id="list-listening-sessions" tabindex="-1"><code>list_listening_sessions</code> <a class="header-anchor" href="#list-listening-sessions" aria-label="Permalink to “list_listening_sessions”">​</a></h3><p><strong>List listening sessions</strong> — read-only</p><p>The playback sessions of the current user, newest first — each entry is one listening stretch with device, position and time listened.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>no</td><td>0-based page number, default 0</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>Number of entries to return, default 10, max 100</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-bookmarks" tabindex="-1"><code>list_bookmarks</code> <a class="header-anchor" href="#list-bookmarks" aria-label="Permalink to “list_bookmarks”">​</a></h3><p><strong>List bookmarks</strong> — read-only</p><p>The bookmarks of the current user — either all of them, or those of one library item. A bookmark is a named position in seconds. Audiobookshelf has no bookmarks endpoint: they are a field on the account, so this reads /api/me and filters here. That is why there is no pagination — you get all of them.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>no</td><td>Restrict the result to the bookmarks of this library item</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-collections" tabindex="-1"><code>list_collections</code> <a class="header-anchor" href="#list-collections" aria-label="Permalink to “list_collections”">​</a></h3><p><strong>List collections</strong> — read-only</p><p>Lists collections — the curated, ordered groups of books. Without library_id it returns the collections of every accessible library. Collections are shared server-wide; playlists are private per user.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>no</td><td>Restrict the result to this library</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-collection" tabindex="-1"><code>get_collection</code> <a class="header-anchor" href="#get-collection" aria-label="Permalink to “get_collection”">​</a></h3><p><strong>Get collection</strong> — read-only</p><p>Fetches one collection with the books it contains, in order.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>string</td><td>yes</td><td>Collection id, as returned by list_collections</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="list-playlists" tabindex="-1"><code>list_playlists</code> <a class="header-anchor" href="#list-playlists" aria-label="Permalink to “list_playlists”">​</a></h3><p><strong>List playlists</strong> — read-only</p><p>Lists the playlists of the API key’s user. Without library_id it returns the playlists of every accessible library. Playlists are private per user and can hold books or podcast episodes; collections are shared server-wide and hold books only.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>no</td><td>Restrict the result to this library</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h3 id="get-playlist" tabindex="-1"><code>get_playlist</code> <a class="header-anchor" href="#get-playlist" aria-label="Permalink to “get_playlist”">​</a></h3><p><strong>Get playlist</strong> — read-only</p><p>Fetches one playlist with its entries, in order.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>playlist_id</code></td><td>string</td><td>yes</td><td>Playlist id, as returned by list_playlists</td></tr><tr><td><code>detail</code></td><td><code>&quot;compact&quot;</code> | <code>&quot;full&quot;</code></td><td>no</td><td>&quot;compact&quot; (default) returns a projection with the fields that matter for browsing; &quot;full&quot; returns the raw Audiobookshelf object including audio files, tracks and chapters, which is very large.</td></tr></tbody></table><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="set-media-progress" tabindex="-1"><code>set_media_progress</code> <a class="header-anchor" href="#set-media-progress" aria-label="Permalink to “set_media_progress”">​</a></h3><p><strong>Set media progress</strong> — write, <strong>essential</strong></p><p>Creates or updates the listening progress of the API key’s user for one book or podcast episode. Set is_finished=true to mark it as finished, is_finished=false to reopen it (which resets the position to 0), or current_time to jump to a position in seconds. Audiobookshelf also marks an item finished on its own once less than ten seconds remain.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>episode_id</code></td><td>string</td><td>no</td><td>Podcast episode id — required to address a podcast episode, omitted for books</td></tr><tr><td><code>current_time</code></td><td>number</td><td>no</td><td>New playback position in seconds</td></tr><tr><td><code>progress</code></td><td>number</td><td>no</td><td>Progress as a fraction between 0 and 1. Only used when is_finished is not given.</td></tr><tr><td><code>is_finished</code></td><td>boolean</td><td>no</td><td>Mark the item as finished (true) or unfinished (false)</td></tr><tr><td><code>hide_from_continue_listening</code></td><td>boolean</td><td>no</td><td>Hide the item from the &quot;Continue Listening&quot; shelf without changing its position</td></tr></tbody></table><h3 id="delete-media-progress-👤" tabindex="-1"><code>delete_media_progress</code> 👤 <a class="header-anchor" href="#delete-media-progress-👤" aria-label="Permalink to “delete_media_progress 👤”">​</a></h3><p><strong>Delete media progress</strong> — write, destructive</p><p>Deletes a progress record of the API key’s user, which removes the listening history for that item — position, finished state and dates. Takes the media progress id (field &quot;id&quot; of get_media_progress), not the library item id. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>media_progress_id</code></td><td>string</td><td>yes</td><td>Media progress id, from the &quot;id&quot; field of get_media_progress</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="create-bookmark" tabindex="-1"><code>create_bookmark</code> <a class="header-anchor" href="#create-bookmark" aria-label="Permalink to “create_bookmark”">​</a></h3><p><strong>Create bookmark</strong> — write</p><p>Creates a bookmark at a position of a book for the API key’s user. The position in seconds is the bookmark’s identity — a second bookmark at the same second is rejected.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>time</code></td><td>number</td><td>yes</td><td>Position in seconds where the bookmark is placed</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td>Bookmark title</td></tr></tbody></table><h3 id="update-bookmark" tabindex="-1"><code>update_bookmark</code> <a class="header-anchor" href="#update-bookmark" aria-label="Permalink to “update_bookmark”">​</a></h3><p><strong>Update bookmark</strong> — write, destructive</p><p>Renames the bookmark at a given position. The position itself cannot be changed — delete the bookmark and create a new one for that.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>time</code></td><td>number</td><td>yes</td><td>Position in seconds identifying the bookmark</td></tr><tr><td><code>title</code></td><td>string</td><td>yes</td><td>New bookmark title</td></tr></tbody></table><h3 id="delete-bookmark-👤" tabindex="-1"><code>delete_bookmark</code> 👤 <a class="header-anchor" href="#delete-bookmark-👤" aria-label="Permalink to “delete_bookmark 👤”">​</a></h3><p><strong>Delete bookmark</strong> — write, destructive</p><p>Deletes the bookmark at a given position. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_item_id</code></td><td>string</td><td>yes</td><td>Library item id, as returned by list_library_items or search_library</td></tr><tr><td><code>time</code></td><td>number</td><td>yes</td><td>Position in seconds identifying the bookmark</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="create-collection" tabindex="-1"><code>create_collection</code> <a class="header-anchor" href="#create-collection" aria-label="Permalink to “create_collection”">​</a></h3><p><strong>Create collection</strong> — write</p><p>Creates a collection of books. Audiobookshelf rejects empty collections, so at least one library item id is required, and every item must be a book from the given library.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library the collection belongs to</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Collection name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Optional description</td></tr><tr><td><code>library_item_ids</code></td><td>string[]</td><td>yes</td><td>Library item ids of books</td></tr></tbody></table><h3 id="update-collection-👤" tabindex="-1"><code>update_collection</code> 👤 <a class="header-anchor" href="#update-collection-👤" aria-label="Permalink to “update_collection 👤”">​</a></h3><p><strong>Update collection</strong> — write, destructive</p><p>Renames a collection, changes its description or reorders its books. library_item_ids ONLY REORDERS. It cannot add or remove anything: Audiobookshelf sorts the books the collection already has by their position in this list, so an id that is not currently in the collection is ignored, and a book you leave out is not removed — it moves to the FRONT. Pass every current book, in the order you want. Use add_books_to_collection and remove_books_from_collection to change membership. Reordering asks a person first, because the order somebody arranged cannot be reconstructed afterwards; renaming and re-describing do not. Where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>string</td><td>yes</td><td>Collection id, as returned by list_collections</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>New name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>New description</td></tr><tr><td><code>library_item_ids</code></td><td>string[]</td><td>no</td><td>The books the collection already has, in the order you want them. Reorders only — it adds nothing and removes nothing.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="add-books-to-collection" tabindex="-1"><code>add_books_to_collection</code> <a class="header-anchor" href="#add-books-to-collection" aria-label="Permalink to “add_books_to_collection”">​</a></h3><p><strong>Add books to collection</strong> — write</p><p>Adds one or more books to an existing collection. Books already in the collection are ignored; books from a different library are rejected.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>string</td><td>yes</td><td>Collection id, as returned by list_collections</td></tr><tr><td><code>library_item_ids</code></td><td>string[]</td><td>yes</td><td>Library item ids of books</td></tr></tbody></table><h3 id="remove-books-from-collection-👤" tabindex="-1"><code>remove_books_from_collection</code> 👤 <a class="header-anchor" href="#remove-books-from-collection-👤" aria-label="Permalink to “remove_books_from_collection 👤”">​</a></h3><p><strong>Remove books from collection</strong> — write, destructive</p><p>Removes books from a collection. The books themselves are untouched — only their membership in the collection ends, and it can be restored with add_books_to_collection. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>string</td><td>yes</td><td>Collection id, as returned by list_collections</td></tr><tr><td><code>library_item_ids</code></td><td>string[]</td><td>yes</td><td>Library item ids of books</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="delete-collection-👤" tabindex="-1"><code>delete_collection</code> 👤 <a class="header-anchor" href="#delete-collection-👤" aria-label="Permalink to “delete_collection 👤”">​</a></h3><p><strong>Delete collection</strong> — write, destructive</p><p>Deletes a collection. The books stay in the library, but the curated list and its order are gone. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it. Requires an Audiobookshelf account with delete permission.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>collection_id</code></td><td>string</td><td>yes</td><td>Collection id, as returned by list_collections</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="create-playlist" tabindex="-1"><code>create_playlist</code> <a class="header-anchor" href="#create-playlist" aria-label="Permalink to “create_playlist”">​</a></h3><p><strong>Create playlist</strong> — write</p><p>Creates a playlist for the API key’s user. Unlike a collection it may start out empty and it may hold podcast episodes.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>library_id</code></td><td>string</td><td>yes</td><td>Library the playlist belongs to</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Playlist name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>Optional description</td></tr><tr><td><code>items</code></td><td>object[]</td><td>no</td><td>Initial entries, optional</td></tr></tbody></table><h3 id="update-playlist-👤" tabindex="-1"><code>update_playlist</code> 👤 <a class="header-anchor" href="#update-playlist-👤" aria-label="Permalink to “update_playlist 👤”">​</a></h3><p><strong>Update playlist</strong> — write, destructive</p><p>Renames a playlist, changes its description or reorders its entries. items ONLY REORDERS. It cannot add or remove anything, and it must contain EXACTLY the entries the playlist already has: Audiobookshelf refuses a list of a different length with HTTP 400 &quot;Invalid playlist items. Length mismatch&quot;. Read the current entries with get_playlist first, then send them in the order you want. Use add_items_to_playlist and remove_items_from_playlist to change membership. The library of a playlist cannot be changed. Reordering asks a person first, because the order somebody arranged cannot be reconstructed afterwards; renaming and re-describing do not. Where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>playlist_id</code></td><td>string</td><td>yes</td><td>Playlist id, as returned by list_playlists</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td>New name</td></tr><tr><td><code>description</code></td><td>string</td><td>no</td><td>New description</td></tr><tr><td><code>items</code></td><td>object[]</td><td>no</td><td>Exactly the entries the playlist already has, in the order you want them. Reorders only; a list of a different length is refused with HTTP 400.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="add-items-to-playlist" tabindex="-1"><code>add_items_to_playlist</code> <a class="header-anchor" href="#add-items-to-playlist" aria-label="Permalink to “add_items_to_playlist”">​</a></h3><p><strong>Add items to playlist</strong> — write</p><p>Appends books or podcast episodes to a playlist. All entries must come from the playlist’s library and match its kind — a podcast playlist needs an episode_id on every entry, a book playlist on none.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>playlist_id</code></td><td>string</td><td>yes</td><td>Playlist id, as returned by list_playlists</td></tr><tr><td><code>items</code></td><td>object[]</td><td>yes</td><td></td></tr></tbody></table><h3 id="remove-items-from-playlist-👤" tabindex="-1"><code>remove_items_from_playlist</code> 👤 <a class="header-anchor" href="#remove-items-from-playlist-👤" aria-label="Permalink to “remove_items_from_playlist 👤”">​</a></h3><p><strong>Remove items from playlist</strong> — write, destructive</p><p>Removes entries from a playlist. The media itself is untouched and the entries can be added back with add_items_to_playlist. Note that Audiobookshelf deletes a playlist automatically once its last entry is removed. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>playlist_id</code></td><td>string</td><td>yes</td><td>Playlist id, as returned by list_playlists</td></tr><tr><td><code>items</code></td><td>object[]</td><td>yes</td><td></td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table><h3 id="delete-playlist-👤" tabindex="-1"><code>delete_playlist</code> 👤 <a class="header-anchor" href="#delete-playlist-👤" aria-label="Permalink to “delete_playlist 👤”">​</a></h3><p><strong>Delete playlist</strong> — write, destructive</p><p>Deletes a playlist. The media stays in the library. Asks a person first; where the client cannot show a dialog, call once to receive a token and again with it.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>playlist_id</code></td><td>string</td><td>yes</td><td>Playlist id, as returned by list_playlists</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Token from the first call of this tool</td></tr></tbody></table>`,185)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};